// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Всё, что знаем о проекте, в одном месте: что пришло, лист канала, строка
// проекта, шаблон канала, этапы и пункты канала. Все узлы ниже берут данные отсюда.
const inc = $('Разбираем входящее').first().json;
let catalog = {};
try { catalog = $('Находим лист канала').first().json || {}; } catch (e) {}
let row = {};
try { row = $('Читаем строку проекта').first().json || {}; } catch (e) {}
let tmpl = {};
try { tmpl = $('Читаем шаблоны канала').first().json || {}; } catch (e) {}
let stageRows = [];
try { stageRows = $('Читаем этапы').all().map(i => i.json || {}); } catch (e) {}
let itemRows = [];
try { itemRows = $('Читаем пункты').all().map(i => i.json || {}); } catch (e) {}

const found = !!row.sys_ProjectID && String(row.sys_ProjectID).trim() === inc.projectId;
const stages = stParseStages(stageRows);
const items = itParseItems(itemRows);

return [{
  json: {
    ...inc,
    sheetName: String(catalog.SheetName || '').trim(),
    found,
    row: found ? row : {},
    tmpl,
    stages,
    items,
    setupProblem: !stages.length ? 'В листе «Этапы» нет строк для этого канала — не знаю, кто работает.' : '',
    status: found ? String(row.sys_Status || '').trim() : '',
  }
}];

// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Кто отвечает на это сообщение — решает таблица (лист «Этапы»), не код.
// Текущий этап — первый по порядку незавершённый (не подчинённый).
// Обращение «✍️ …» / «Писателю: …» — к названному этапу напрямую.
const ctx = $('Контекст проекта').first().json;
const row = ctx.row || {};
const stages = ctx.stages || [];
const items = ctx.items || [];
const state = stParseState(row.sys_EditorState);
const approvedUrl = String(row.ai_ApprovedImageUrl || '').trim();
const isStart = ctx.kind === 'stageStart';

const addressed = isStart ? null : stAddressed(stages, ctx.text);
const current = stCurrent(stages, items, state, approvedUrl);
// Всё готово, а автор пишет без обращения — отвечает последний этап, который говорит с автором
// словами (у кого есть пункты): художнику без обращения сообщение не уходит — он бы его нарисовал.
const lastAuthor = [...stages].reverse().find(s => s.talks === 'author' && s.items.length) || null;
const stage = addressed ? addressed.stage : (current || (isStart ? null : lastAuthor));
let userText = addressed ? addressed.rest : String(ctx.text || '');
const photo = ctx.photo && ctx.photo.length ? ctx.photo : null;
if (!userText.trim()) userText = photo ? '(фото без подписи)' : '';

let mode = 'none';
let sayText = '';
let silent = false;
if (ctx.setupProblem) {
  mode = 'say'; sayText = ctx.setupProblem;
} else if (!stage) {
  mode = 'done'; // все этапы завершены — дальше сводка / запись
} else if (stage.picture && !stage.items.length) {
  // Художник: сообщение автора — это задание. Ответ на картинку или «правка …» — правка.
  if (isStart) {
    if (stage.talks === 'author' || !String(row.ai_UserBrief || '').trim()) {
      mode = 'say';
      sayText = `${stage.icon} ${stage.name}: жду задание — опишите, что на картинке.`;
    } else {
      mode = 'draw'; userText = String(row.ai_UserBrief || ''); silent = true;
    }
  } else if (!userText.trim()) {
    mode = 'say'; sayText = `${stage.icon} ${stage.name}: напишите задание словами.`;
  } else {
    const e = userText.match(/^\s*правк[аиу](?![а-яё])(?:\s*(?:вариант[а]?|№)?\s*(\d+))?[\s:,.!—–-]*/iu);
    if (e || ctx.replyVariant) {
      mode = 'edit';
      if (e) userText = userText.slice(e[0].length);
    } else mode = 'draw';
  }
} else {
  mode = 'model';
  silent = stage.talks !== 'author' && !addressed;
}

const editVariant = (() => {
  const e = String(ctx.text || '').match(/правк[аиу]\s*(?:вариант[а]?|№)?\s*(\d+)/iu);
  return e ? Number(e[1]) : (ctx.replyVariant || null);
})();

return [{
  json: {
    mode,
    stageIcon: stage ? stage.icon : '',
    stageName: stage ? stage.name : '',
    userText,
    photo: mode === 'model' ? photo : null,
    isStart,
    event: ctx.event || '',
    silent,
    sayText,
    editVariant,
    fromAuthor: !isStart,
    // фото этапу, чей пункт показывается превью «оживление», — это разметка: её читает сборщик
    needMarks: mode === 'model' && !!photo && !!approvedUrl && !!stage &&
      items.some(it => stScope(stages, stage).items.includes(it.n) && /оживл/.test(it.preview || '')),
    needGrid: mode === 'model' && !!(stage && stage.grid) && !!approvedUrl,
    needConv: mode === 'model' && !silent && !String((state.stages[bareIcon(stage ? stage.icon : '')] || {}).conv || '').trim(),
  }
}];

// Фото автора → data URL, чтобы Редактор увидел саму картинку.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const item = $input.first();
let mimeType = (item.binary && item.binary.data && item.binary.data.mimeType) || '';
if (!mimeType || mimeType === 'application/octet-stream') mimeType = 'image/jpeg';
return [{ json: { userImageUrl: `data:${mimeType};base64,${buffer.toString('base64')}` } }];

// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Запрос к этапу (любому: писатель, технический, редактор…). Кто он, что знает
// и что делает — из таблицы: лист «Этапы», лист «Пункты», колонки Templates с его значком.
const ctx = $('Контекст проекта').first().json;
const plan = $('Кто отвечает').first().json;
const row = ctx.row || {};
const stages = ctx.stages || [];
const items = ctx.items || [];
const stage = stages.find(s => bareIcon(s.icon) === bareIcon(plan.stageIcon));
if (!stage) throw new Error('Этап ' + plan.stageIcon + ' не найден в листе «Этапы»');
const state = stParseState(row.sys_EditorState);
const sc = stScope(stages, stage);
const st = stStage(state, stage.icon);
const approvedUrl = String(row.ai_ApprovedImageUrl || '').trim();
const brief = String(row.ai_UserBrief || '').trim();

// Разговор этапа: свой у каждого этапа (чистая голова). Молчаливый этап — без разговора.
let conversationId = '';
let isNew = false;
if (!plan.silent) {
  conversationId = String(st.conv || '').trim();
  if (!conversationId) {
    try { conversationId = $('OpenAI: создаём разговор').first().json.id; isNew = true; } catch (e) {}
  }
  if (!conversationId) throw new Error('Нет разговора для этапа ' + stage.name);
}
const pendingCallId = plan.silent || isNew ? '' : String(st.pending || '').trim();

let userImageUrl = '';
try { userImageUrl = $('Фото в base64').first().json.userImageUrl || ''; } catch (e) {}

const kb = kbForStage(ctx.tmpl, stage.icon, [plan.userText, brief].join(' '));

// ── Картинки: каждая показывается этапу один раз и дальше живёт в истории разговора ──
let variants = [];
try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
if (!Array.isArray(variants)) variants = [];
const seen = new Set(plan.silent ? [] : st.seen);
const images = [];
// key — что помнить в состоянии (картинку с сеткой помним по метке, а не по её огромным данным)
const addImage = (url, label, key) => { const k = key || url; if (url && !seen.has(k)) { images.push({ url, label }); seen.add(k); } };
let gridUrl = '';
try { gridUrl = ($('Сервер: сетка').first().json || {}).dataUrl || ''; } catch (e) {}
if (gridUrl && approvedUrl) addImage(gridUrl, 'согласованная картинка выпуска с сеткой процентов: синие подписи — проценты слева направо, красные — сверху вниз', 'grid:' + approvedUrl);
else if (approvedUrl) addImage(approvedUrl, 'согласованная картинка выпуска');
if (sc.picture) variants.forEach(v => addImage(v.url, 'вариант ' + v.n + ' этого выпуска'));

// ── Карточка выпуска ──
const who = n => { const s = stages.find(x => x.items.includes(n)); return s ? s.name : '—'; };
const itemLines = items.map(it => {
  const status = state.agreed[it.n] ? 'СОГЛАСОВАНО' : (it.n in state.items ? 'предложено, ждёт согласования' : 'ещё не предлагалось');
  const mine = sc.items.includes(it.n) ? 'твой пункт' : 'делает ' + who(it.n);
  const text = itShow(state, it);
  return `  ${it.n}. ${it.name} [${status}; ${mine}]` + (text ? '\n' + text.split('\n').map(l => '     ' + l).join('\n') : '');
}).join('\n');
const stageLines = stages.map(s => `  ${s.icon} ${s.name}: ${stComplete(stages, items, state, approvedUrl, s) ? 'готово' : 'в работе'}`).join('\n');
const card = [
  `Выпуск ${ctx.projectId}.`,
  brief ? `Бриф автора: ${brief}` : '',
  `Картинка: ${approvedUrl ? 'согласована' : 'ещё не согласована'}${variants.length ? `; вариантов: ${variants.length}` : ''}.`,
  'Этапы:', stageLines,
  'Пункты:', itemLines || '  (лист «Пункты» пуст)',
].filter(Boolean).join('\n');

const myItems = items.filter(it => sc.items.includes(it.n));
const itemsSpec = myItems.map(it => `  ${it.n}. ${it.name}${it.hint ? ' — ' + it.hint : ''}${it.canEmpty ? ' (можно оставить пустым: "-")' : ''}`).join('\n');
const subs = sc.subs;
const talk = plan.silent
  ? 'Ты работаешь молча, по заданию: сразу вызови propose_items со своими пунктами.'
  : 'Ты говоришь с автором напрямую.';

const tools = [{ type: 'web_search' }];
const toolLines = [];
if (myItems.length) {
  tools.push({
    type: 'function', name: 'propose_items',
    description: 'Предложить или изменить свои пункты и/или отметить пункты, которые автор явно согласовала.',
    parameters: { type: 'object', properties: {
      items: { type: 'array', description: 'Только пункты, которые предлагаешь или меняешь сейчас', items: { type: 'object', properties: {
        n: { type: 'integer', description: 'Номер пункта' },
        text: { type: 'string', description: 'Текст пункта — ровно то, что уйдёт в таблицу; "-" если пункт не нужен' },
        ru: { type: 'string', description: 'Русский перевод для показа автору, если пункт не по-русски; в таблицу не идёт' },
      }, required: ['n', 'text'] } },
      agreed: { type: 'array', items: { type: 'integer' }, description: 'Номера пунктов, которые автор ЯВНО одобрила' },
      reopen: { type: 'array', items: { type: 'integer' }, description: 'Номера согласованных пунктов, которые автор решила пересмотреть' },
      message: { type: 'string', description: 'Реплика автору (пункты система покажет сама)' },
    }, required: ['message'] },
  });
  toolLines.push('- propose_items — предложить/изменить свои пункты и отметить согласованные автором (agreed — только то, что она явно одобрила; «всё ок» — все показанные). Система сама покажет автору пункты, ждущие согласования; в message их не переписывай. Изменённый пункт снова ждёт согласования.');
}
if (kb.notesKey && !plan.silent) {
  tools.push({
    type: 'function', name: 'save_note',
    description: 'Сохранить твою памятку (колонка таблицы, её видишь только ты и в следующих выпусках).',
    parameters: { type: 'object', properties: {
      notes: { type: 'string', description: 'ПОЛНЫЙ текст памятки: прежняя + новое' },
      message: { type: 'string', description: 'Реплика автору' },
    }, required: ['notes', 'message'] },
  });
  toolLines.push('- save_note — записать в твою памятку то, что стоит помнить в следующих выпусках (замечания автора, её вкус). Передавай полный текст.');
}
if (subs.length && !plan.silent) {
  tools.push({
    type: 'function', name: 'delegate',
    description: 'Поручить работу этапу, который работает по твоему заданию.',
    parameters: { type: 'object', properties: {
      stage: { type: 'string', enum: subs.map(s => s.name), description: 'Кому поручаешь' },
      task: { type: 'string', description: 'Задание: что сделать' },
      variant: { type: 'integer', description: 'Для правки картинки: номер варианта, который правим' },
      edit: { type: 'boolean', description: 'Для картинки: true — правка уже нарисованного варианта' },
      message: { type: 'string', description: 'Реплика автору' },
    }, required: ['stage', 'task', 'message'] },
  });
  toolLines.push('- delegate — поручить работу: ' + subs.map(s => `${s.icon} ${s.name} (${s.picture ? 'картинка' : 'пункты ' + s.items.join(', ')})`).join('; ') + '. Он получает только твоё задание и свои знания из таблицы.');
}
if (sc.picture && !stage.picture && !plan.silent) {
  tools.push({
    type: 'function', name: 'approve_image',
    description: 'Автор согласовала картинку словами.',
    parameters: { type: 'object', properties: {
      variant: { type: 'integer', description: 'Номер согласованного варианта' },
      message: { type: 'string', description: 'Реплика автору' },
    }, required: ['message'] },
  });
  toolLines.push('- approve_image — автор согласовала картинку словами (номер варианта, если их несколько).');
}

const instructions = `Ты — ${stage.icon} ${stage.name} канала "${ctx.sheetName}". ${talk}
Кто ты, как говоришь и что делаешь — в твоих знаниях из таблицы канала ниже. Здесь — только то, как устроена система.

ТВОИ ПУНКТЫ В ЭТОМ ВЫПУСКЕ
${itemsSpec || '  (своих пунктов нет)'}

ИНСТРУМЕНТЫ. За один ответ — не больше одного; если ничего не нужно — просто отвечай текстом.
${toolLines.join('\n')}
Когда все твои пункты согласованы, твой этап завершён — система сама передаст выпуск дальше.
Если по смыслу твоих слов что-то предложено, согласовано или изменено, а инструмент не вызван — вызови его в этом же ответе.

ТВОИ ЗНАНИЯ ИЗ ТАБЛИЦЫ КАНАЛА:
${kb.text || '(пусто — в Templates нет колонок с твоим значком)'}

КАРТОЧКА ВЫПУСКА (актуальна на этот ход; если расходится с тем, что ты помнишь, — верь карточке):
${card}`;

// ── Сообщение ──
const text = plan.isStart
  ? `[Служебное сообщение] ${plan.event || 'Предыдущий этап завершён.'} Сейчас твой этап — начни по своим правилам.`
  : (plan.userText || '(пустое сообщение)');
let marksText = '';
try { marksText = ($('Сервер: разметка').first().json || {}).text || ''; } catch (e) {}
const content = [{ type: 'input_text', text: text + (marksText
  ? '\n\n[Разметка автора — красные штрихи на её картинке, слева направо; числа — проценты кадра, прочитаны точно]\n' + marksText
  : '') }];
if (userImageUrl) {
  content.push({ type: 'input_text', text: '(Фото, которое автор прислала в этом сообщении:)' });
  content.push({ type: 'input_image', image_url: userImageUrl });
}
for (const img of images) {
  content.push({ type: 'input_text', text: `(Служебно: ${img.label})` });
  content.push({ type: 'input_image', image_url: img.url });
}
const input = [];
if (pendingCallId) input.push({ type: 'function_call_output', call_id: pendingCallId, output: 'Выполнено. Актуальный результат — в карточке выпуска.' });
input.push({ role: 'user', content: content.length > 1 ? content : text });

const requestBody = {
  model: stage.model || 'gpt-5',
  instructions,
  input,
  tools,
  tool_choice: plan.silent && myItems.length ? { type: 'function', name: 'propose_items' } : 'auto',
  parallel_tool_calls: false,
  truncation: 'auto',
};
if (conversationId) requestBody.conversation = conversationId;
if (['low', 'medium', 'high'].includes(stage.effort)) requestBody.reasoning = { effort: stage.effort };

return [{ json: { requestBody, conversationId, seen: Array.from(seen), stageIcon: stage.icon } }];

// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Разбираем ответ этапа: текст и (не больше одного) вызов инструмента.
const response = $input.first().json || {};
const prep = $('Готовим запрос этапу').first().json;
const ctx = $('Контекст проекта').first().json;
const plan = $('Кто отвечает').first().json;
const row = ctx.row || {};
const stages = ctx.stages || [];
const items = ctx.items || [];
const stage = stages.find(s => bareIcon(s.icon) === bareIcon(prep.stageIcon));
const sc = stScope(stages, stage);
const output = response.output || [];

const plainText = output.filter(i => i.type === 'message')
  .flatMap(i => (i.content || []).filter(c => c.type === 'output_text').map(c => c.text)).join('\n\n').trim();
const callItem = output.find(i => i.type === 'function_call');
let functionName = null, callId = null, args = {};
if (callItem) {
  functionName = callItem.name; callId = callItem.call_id;
  try { args = JSON.parse(callItem.arguments || '{}'); } catch (e) { args = {}; }
}
let message = (args.message || plainText || '').trim();
if (response.error || (!callItem && !plainText)) {
  message = `⚠️ ${stage.name} не ответил${response.error ? ': ' + (response.error.message || response.error) : ''}. Напишите ещё раз.`;
}

const state = stParseState(row.sys_EditorState);
const st = stStage(state, stage.icon);
if (!plan.silent) {
  st.conv = prep.conversationId || st.conv;
  st.pending = callId || '';
  st.seen = prep.seen || st.seen;
}

let action = 'chat';
let changed = [];
let note = null;
let delegate = null;
let art = null;
let approveUrl = '';
let approveVariant = null;

if (functionName === 'propose_items') {
  changed = itApply(state, items, sc.items, args, plan.silent || !stage.approve);
  action = 'text_block';
} else if (functionName === 'save_note') {
  const kb = kbForStage(ctx.tmpl, stage.icon, '');
  if (kb.notesKey) note = { key: kb.notesKey, text: String(args.notes || '') };
} else if (functionName === 'delegate') {
  const sub = sc.subs.find(s => s.name === args.stage);
  if (sub && sub.picture && !sub.items.length) {
    art = artBuild(ctx, sub, String(args.task || ''), !!args.edit || !!args.variant, args.variant || null);
    action = art.action;
    if (action === 'chat') message = [message, art.messageToUser].filter(Boolean).join('\n\n');
  } else if (sub) {
    delegate = { stageIcon: sub.icon, stageName: sub.name, task: String(args.task || '') };
    action = 'delegate';
  }
} else if (functionName === 'approve_image') {
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const found = args.variant ? variants.find(v => Number(v.n) === Number(args.variant)) : (variants.length === 1 ? variants[0] : null);
  if (found && found.url) { approveUrl = found.url; approveVariant = found.n; action = 'approved'; }
  else message += `\n\n(Не поняла, какой вариант согласован${variants.length ? ': есть ' + variants.map(v => v.n).join(', ') : ''}.)`;
}

return [{ json: {
  action, functionName, callId, message, changed, note, delegate, art,
  approveUrl, approveVariant,
  editorState: JSON.stringify(state),
  stageIcon: stage.icon, stageName: stage.name,
} }];

// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Поручение этапу, который работает по заданию другого (например, Редактор → Писатель).
// Он получает только задание, свои знания из таблицы и картинку — молча, без разговора.
const ctx = $('Контекст проекта').first().json;
const r = $('Разбираем ответ этапа').first().json;
const row = ctx.row || {};
const stages = ctx.stages || [];
const items = ctx.items || [];
const sub = stages.find(s => bareIcon(s.icon) === bareIcon(r.delegate.stageIcon));
const state = stParseState(r.editorState);
const kb = kbForStage(ctx.tmpl, sub.icon, r.delegate.task + ' ' + String(row.ai_UserBrief || ''));
const myItems = items.filter(it => sub.items.includes(it.n));
const approvedUrl = String(row.ai_ApprovedImageUrl || '').trim();
const current = myItems.map(it => { const t = itShow(state, it); return t ? `${it.n}. ${it.name}:\n${t}` : ''; }).filter(Boolean).join('\n\n');

const instructions = `Ты — ${sub.icon} ${sub.name} канала "${ctx.sheetName}". Ты работаешь по заданию: сразу вызови propose_items со своими пунктами.

ТВОИ ПУНКТЫ
${myItems.map(it => `  ${it.n}. ${it.name}${it.hint ? ' — ' + it.hint : ''}`).join('\n')}

ТВОИ ЗНАНИЯ ИЗ ТАБЛИЦЫ КАНАЛА:
${kb.text || '(пусто)'}`;

const content = [{ type: 'input_text', text: 'ЗАДАНИЕ:\n' + r.delegate.task + (current ? '\n\nСейчас в твоих пунктах (для сведения):\n' + current : '') }];
if (approvedUrl) {
  content.push({ type: 'input_text', text: '(Согласованная картинка выпуска:)' });
  content.push({ type: 'input_image', image_url: approvedUrl });
}
const tools = [{
  type: 'function', name: 'propose_items', description: 'Твои пункты.',
  parameters: { type: 'object', properties: {
    items: { type: 'array', items: { type: 'object', properties: {
      n: { type: 'integer' }, text: { type: 'string' }, ru: { type: 'string', description: 'Русский перевод для показа автору, если пункт не по-русски' },
    }, required: ['n', 'text'] } },
    message: { type: 'string' },
  }, required: ['items'] },
}];
const requestBody = {
  model: sub.model || 'gpt-5', instructions, input: [{ role: 'user', content }], tools,
  tool_choice: { type: 'function', name: 'propose_items' },
};
if (['low', 'medium', 'high'].includes(sub.effort)) requestBody.reasoning = { effort: sub.effort };
return [{ json: { requestBody } }];

// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Итог хода — все узлы ниже читают только его. Сюда приходят три пути:
// художник (задание автора), этап-модель (с поручением подчинённому или без),
// служебная реплика. Здесь же решаем переход к следующему этапу.
const ctx = $('Контекст проекта').first().json;
const plan = $('Кто отвечает').first().json;
const row = ctx.row || {};
const stages = ctx.stages || [];
const items = ctx.items || [];
const stage = stages.find(s => bareIcon(s.icon) === bareIcon(plan.stageIcon)) || null;
const before = stParseState(row.sys_EditorState);
let state = stParseState(row.sys_EditorState);
const approvedBefore = String(row.ai_ApprovedImageUrl || '').trim();

let action = 'chat';
let message = '';
let note = null;
let art = null;
let approveUrl = '';
let approveVariant = null;
let changed = [];
let speaker = stage;
// Картинку без согласования автора (этап «авто» или молчаливый) согласуем сами после рисунка.
let autoApprove = false;

if (plan.mode === 'say') {
  message = plan.sayText;
  speaker = null;
} else if (plan.mode === 'done') {
  action = 'done';
} else if (plan.mode === 'draw' || plan.mode === 'edit') {
  art = artBuild(ctx, stage, plan.userText, plan.mode === 'edit', plan.editVariant);
  autoApprove = !stage.approve || stage.talks === 'none';
  action = art.action;
  message = art.action === 'chat' ? art.messageToUser : (plan.mode === 'edit' ? 'поправляю 🎨' : 'рисую 🎨');
} else if (plan.mode === 'model') {
  const r = $('Разбираем ответ этапа').first().json;
  state = stParseState(r.editorState);
  action = r.action; message = r.message; note = r.note; changed = r.changed || [];
  approveUrl = r.approveUrl; approveVariant = r.approveVariant;
  if (r.art) { art = r.art; autoApprove = !stage.approve; }
  if (r.action === 'delegate') {
    // Подчинённый этап прислал свои пункты.
    const sub = stages.find(s => bareIcon(s.icon) === bareIcon(r.delegate.stageIcon));
    const boss = stage;
    let resp = {};
    try { resp = $('OpenAI: поручение').first().json || {}; } catch (e) {}
    const call = (resp.output || []).find(i => i.type === 'function_call');
    let a = {};
    try { a = JSON.parse((call && call.arguments) || '{}'); } catch (e) { a = {}; }
    const got = itApply(state, items, sub.items, a, !boss.approve);
    changed = [...new Set([...changed, ...got])];
    action = 'text_block';
    if (!call) message = [message, `⚠️ ${sub.icon} ${sub.name} не прислал работу — попросите ещё раз.`].filter(Boolean).join('\n\n');
  }
}

// ── Картинка согласована словами (через этап, который за неё отвечает) ──
const approvedUrl = approveUrl || approvedBefore;

// ── Статус в таблице: только механика для сборщика ──
const cur = ctx.status;
let statusAfter = cur || 'Картинка в работе';
let statusReverted = false;
if (cur !== 'Опубликовано') {
  if (action === 'approved' && !(cur === 'Утверждено' && approveUrl === approvedBefore)) statusAfter = 'Картинка согласована';
  if (cur === 'Утверждено' && changed.length) statusAfter = 'Картинка согласована';
  statusReverted = cur === 'Утверждено' && statusAfter !== 'Утверждено';
}

// ── Переход: этап только что завершился → следующий; всё готово → сводка или запись ──
let transition = 'none';
let event = '';
let nextIcon = '';
if (action === 'done') {
  transition = stages.some(s => s.approve) ? 'summary' : 'package';
} else if (stage && ['text_block', 'approved'].includes(action)) {
  const wasDone = stComplete(stages, items, before, approvedBefore, stage);
  const nowDone = stComplete(stages, items, state, approvedUrl, stage);
  if (nowDone && !wasDone) {
    const next = stCurrent(stages, items, state, approvedUrl);
    if (next) { transition = 'next'; nextIcon = next.icon; event = `Этап «${stage.name}» завершён.`; }
    else transition = stages.some(s => s.approve) ? 'summary' : 'package';
  }
}

// ── Что показать автору ──
const prefix = speaker ? `${speaker.icon} <b>${escapeHtml(speaker.name)}</b>: ` : '';
let text = prefix + escapeHtml(message || '');
if (statusReverted) text += '\n\n⚠️ Статус «Утверждено» снят — после изменений пришлю новую сводку на ✅.';
if (action === 'text_block' && stage) {
  const sc = stScope(stages, stage);
  const mine = items.filter(it => sc.items.includes(it.n));
  const pending = mine.filter(it => !state.agreed[it.n]);
  const done = mine.filter(it => state.agreed[it.n]);
  if (pending.length) {
    text += `\n\n<b>Ждут согласования:</b> ${pending.map(it => it.n).join(', ')}`;
    for (const it of pending) {
      const body = itShow(state, it);
      text += `\n\n<b>${it.n}. ${escapeHtml(it.name)}</b>` + (body ? '\n' + escapeHtml(body) : ' — ещё не предложено');
    }
    text += '\n\nОтвечайте по номеру или по названию пункта.';
  }
  if (done.length) text += '\n\n✔️ Согласовано: ' + done.map(it => `${it.n} ${escapeHtml(it.name)}`).join(', ');
}
if (action === 'approved') text += `\n\n✅ Картинка согласована${approveVariant ? ' (вариант ' + approveVariant + ')' : ''}.`;
text += `\n\nID: ${ctx.projectId}`;
// Превью: изменился пункт, которому в листе «Пункты» положено превью, — сборщик нарисует картинку.
let previewBody = null;
const pvItem = items.find(it => it.preview && changed.includes(it.n) && (state.items[it.n] || {}).text);
if (pvItem && approvedBefore && /оживл/.test(pvItem.preview)) {
  const fx = {};
  for (const key of Object.keys(ctx.tmpl || {})) {        // вид эффектов — колонки 🎬 (как у сборки)
    if (!key.includes('🎬')) continue;
    const label = key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, '');
    const v = String((ctx.tmpl || {})[key] == null ? '' : ctx.tmpl[key]).trim();
    if (label && v) fx[label.charAt(0).toLowerCase() + label.slice(1)] = v;
  }
  previewBody = { ...fx, imageUrl: approvedBefore, fx_Effects: state.items[pvItem.n].text, projectId: ctx.projectId };
}
const chunks = action === 'done' || (!message && action !== 'text_block') ? [] : splitForTelegram(text);

return [{ json: {
  action,
  chunks,
  silentTurn: !!plan.silent,
  note,
  editorState: JSON.stringify(state),
  statusAfter,
  statusReverted,
  approvedUrl: approveUrl,
  approveVariant,
  userBrief: String(row.ai_UserBrief || '').trim() || (plan.fromAuthor ? String(ctx.text || '').trim() : ''),
  transition,
  nextIcon,
  previewBody,
  previewCaption: previewBody ? `${stage ? stage.icon + ' ' : ''}Превью: так это будет выглядеть\n\nID: ${ctx.projectId}` : '',
  autoApprove,
  event,
  // для веток рисования (узлы перенесены из 01_Художник)
  dallePrompt: art ? art.dallePrompt : '',
  revisionInstruction: art ? art.revisionInstruction : '',
  revisionIsNewVariant: true,
  revisionTargetImageUrl: art ? art.revisionTargetImageUrl : '',
  revisionTargetVariantNumber: art ? art.revisionTargetVariantNumber : 1,
  drawRefUrls: art ? art.drawRefUrls : [],
  drawRoles: art ? art.drawRoles : '',
  editRefUrls: art ? art.editRefUrls : [],
  editRoles: art ? art.editRoles : '',
  imageModel: art ? art.imageModel : '',
  projectId: ctx.projectId,
  chatId: ctx.chatId,
  sheetName: ctx.sheetName,
  channelKey: ctx.channelKey,
  stageIcon: stage ? stage.icon : '',
} }];

// Памятка этапа — колонка Templates с его значком и 📝 (имя колонки берётся из таблицы).
const r = $('Итог хода').first().json;
return [{ json: { tmpl_Channel: r.channelKey, [r.note.key]: r.note.text } }];

// Сообщения хода — по одному на кусок (лимит Телеграма); если сказать нечего — один пропуск.
const r = $('Итог хода').first().json;
if (!r.chunks || !r.chunks.length) return [{ json: { skip: true } }];
return r.chunks.map(text => ({ json: { skip: false, chatId: r.chatId, text } }));

// Что делать после хода — ровно одно действие (сколько бы кусков сообщения ни ушло).
const r = $('Итог хода').first().json;
let next = 'none';
if (r.action === 'ready_to_draw') next = 'draw';
else if (r.action === 'revise_point') next = 'edit';
else if (r.transition && r.transition !== 'none') next = r.transition;
return [{ json: { next, preview: !!r.previewBody } }];

// Передаём выпуск следующему этапу: канвас вызывает сам себя (новый запуск
// читает таблицу заново — никакой путаницы с устаревшими данными).
let r = null;
try { r = $('Итог хода').first().json; } catch (e) {}
let ctx = null;
try { ctx = $('Контекст проекта').first().json; } catch (e) {}
let event = r && r.event ? r.event : '';
try { const a = $('Согласуем вариант').first().json; if (a && a.ok) event = `Картинка согласована (вариант ${a.variantNumber}).`; } catch (e) {}
try { const a = $('Авто: согласуем картинку').first().json; if (a && a.ok) event = 'Картинка готова.'; } catch (e) {}
if (!ctx) {
  // новый выпуск: контекста ещё нет — берём из создания проекта
  const p = $('Генерируем ProjectID').first().json;
  return [{ json: { kind: 'stageStart', projectId: p.projectId, channelKey: p.channelKey, chatId: p.chatId, event: 'Новый выпуск.' } }];
}
return [{ json: { kind: 'stageStart', projectId: ctx.projectId, channelKey: ctx.channelKey, chatId: ctx.chatId, event } }];

// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Все этапы завершены: сводка всех пунктов — ровно то, что уйдёт в таблицу и на YouTube —
// и одна кнопка ✅. Состояние берём из этого хода, если он был, иначе из строки.
const ctx = $('Контекст проекта').first().json;
let raw = (ctx.row || {}).sys_EditorState;
try { raw = $('Итог хода').first().json.editorState; } catch (e) {}
const state = stParseState(raw);
const items = ctx.items || [];
let text = '<b>Финальная сводка</b> — все пункты согласованы.';
for (const it of items) text += `\n\n<b>${it.n}. ${escapeHtml(it.name)}</b>\n` + escapeHtml(itShow(state, it) || '— пусто');
text += `\n\nID: ${ctx.projectId}`;
const warn = String((ctx.row || {}).ai_ApprovedImageUrl || '').trim() ? '' : '\n⚠️ Картинка ещё не согласована — сначала согласуйте её, иначе кнопка не сработает.';
return splitForTelegram(text).map((t, i, all) => ({ json: {
  chatId: ctx.chatId, text: t, last: i === all.length - 1,
  buttonText: escapeHtml('Всё верно? Нажмите ✅ — я запишу всё в таблицу и проверю каждое поле.' + warn) + `\n\nID: ${ctx.projectId}`,
  callbackData: 'final|' + ctx.projectId,
} }));

// ── Общий кусок движка этапов (одинаковый в нескольких узлах) ─────────────
// Движок не знает ни ролей, ни пунктов, ни имён колонок с содержанием.
// Сценарий — лист «Этапы», пункты — лист «Пункты», знания — колонки Templates
// со значком этапа. Служебные колонки (⚙️ или без значка) — механика.

function escapeHtml(t) {
  return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Режем длинный текст на куски под лимит Телеграма (4096), стараясь по переносу строки.
function splitForTelegram(text, limit) {
  const LIMIT = limit || 3800;
  const chunks = [];
  let rest = String(text || '');
  while (rest.length > LIMIT) {
    let cut = rest.lastIndexOf('\n', LIMIT);
    if (cut < LIMIT * 0.5) cut = LIMIT;
    chunks.push(rest.slice(0, cut));
    rest = rest.slice(cut).replace(/^\n+/, '');
  }
  if (rest.length) chunks.push(rest);
  if (!chunks.length) return [''];
  // ID проекта — в КАЖДОЙ части: автор может ответить (reply) на любую.
  const idm = String(text || '').match(/\n\nID: (\S+)\s*$/);
  if (idm && chunks.length > 1) {
    for (let i = 0; i < chunks.length - 1; i++) chunks[i] += `\n\n(продолжение ниже)\nID: ${idm[1]}`;
  }
  return chunks;
}

// Служебная колонка по имени (только для ⚙️ / колонок без значка — это кнопки механики).
function findByLabel(row, label) {
  const key = Object.keys(row || {}).find(k => k.replace(/^[^a-zA-Z]+/, '') === label);
  return key ? row[key] : undefined;
}

// Значение строки служебного листа по заголовку (заголовки листов «Этапы»/«Пункты»).
function cell(row, ...names) {
  const norm = s => String(s).toLowerCase().replace(/[^a-zа-яё0-9№]+/giu, '');
  for (const nm of names) {
    const key = Object.keys(row || {}).find(k => norm(k) === norm(nm));
    if (key !== undefined && row[key] != null && String(row[key]).trim() !== '') return String(row[key]).trim();
  }
  return '';
}

// «1, 2, 4-8» / «1,2,4–8» → [1,2,4,5,6,7,8]
function parseNumbers(text) {
  const out = [];
  for (const part of String(text || '').split(/[,;\s]+/)) {
    const m = part.match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (m) { for (let i = +m[1]; i <= +m[2]; i++) out.push(i); continue; }
    if (/^\d+$/.test(part)) out.push(+part);
  }
  return [...new Set(out)];
}

function isEmojiStart(s) { return /^\p{Extended_Pictographic}/u.test(String(s || '').trim()); }
// Значок для сравнения — без вариационного селектора (✍️ и ✍ — один значок).
function bareIcon(s) { return String(s || '').replace(/️/g, '').trim(); }

// ── Этапы ──
// Строка листа «Этапы»: Значок | Кто | С кем говорит | Согласование | Делает | Модель | Усилие
function stParseStages(rows) {
  const list = (rows || []).map(r => {
    const does = cell(r, 'Делает');
    const talksRaw = cell(r, 'С кем говорит').toLowerCase();
    return {
      icon: cell(r, 'Значок'),
      name: cell(r, 'Кто'),
      talksRaw,
      approve: !/авто/i.test(cell(r, 'Согласование')),
      picture: /картин/i.test(does),
      items: parseNumbers(does.replace(/картин\S*/gi, '')),
      model: cell(r, 'Модель'),
      effort: cell(r, 'Усилие').toLowerCase(),
      // «Картинка: с сеткой» — этап видит картинку с сеткой процентов (чтобы точно называть места)
      grid: /сетк/i.test(cell(r, 'Картинка')),
    };
  }).filter(s => s.icon && s.name);
  for (const s of list) {
    if (/^автор/.test(s.talksRaw)) s.talks = 'author';
    else if (!s.talksRaw || /^[-—–]$/.test(s.talksRaw) || /^(никто|сам)/.test(s.talksRaw)) s.talks = 'none';
    else {
      const boss = list.find(b => b !== s && (b.name.toLowerCase() === s.talksRaw || bareIcon(b.icon) === bareIcon(s.talksRaw)));
      s.talks = boss ? 'boss' : 'none';
      s.boss = boss ? boss.icon : '';
    }
  }
  return list;
}

function stSubordinates(stages, stage) {
  return stages.filter(s => s.talks === 'boss' && bareIcon(s.boss) === bareIcon(stage.icon));
}

// Что этап отвечает: свои пункты + пункты подчинённых; картинка — своя или подчинённого.
function stScope(stages, stage) {
  const subs = stSubordinates(stages, stage);
  const items = [...new Set([...stage.items, ...subs.flatMap(s => s.items)])].sort((a, b) => a - b);
  return { items, picture: stage.picture || subs.some(s => s.picture), subs };
}

// ── Пункты ──
// Строка листа «Пункты»: № | Пункт | Колонки | Подсказка | Можно пусто
function itParseItems(rows) {
  return (rows || []).map(r => ({
    n: parseInt(cell(r, '№', 'Номер'), 10),
    name: cell(r, 'Пункт'),
    cols: cell(r, 'Колонки'),
    hint: cell(r, 'Подсказка'),
    canEmpty: /^да/i.test(cell(r, 'Можно пусто')),
    // «Превью: оживление» — после изменения пункта автору приходит картинка-превью от сборщика
    preview: cell(r, 'Превью').toLowerCase(),
  })).filter(i => i.n > 0 && i.name).sort((a, b) => a.n - b.n);
}

// ── Состояние выпуска (sys_EditorState) ──
function stEmptyState() {
  return { v: 2, items: {}, agreed: {}, stages: {} };
}
function stParseState(raw) {
  let p = null;
  try { p = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { p = null; }
  if (!p || typeof p !== 'object' || p.v !== 2) return stEmptyState();
  const s = stEmptyState();
  s.items = p.items && typeof p.items === 'object' ? p.items : {};
  s.agreed = p.agreed && typeof p.agreed === 'object' ? p.agreed : {};
  s.stages = p.stages && typeof p.stages === 'object' ? p.stages : {};
  return s;
}
function stStage(state, icon) {
  const k = bareIcon(icon);
  state.stages[k] = state.stages[k] || { conv: '', pending: '', seen: [] };
  if (!Array.isArray(state.stages[k].seen)) state.stages[k].seen = [];
  return state.stages[k];
}

function stItemDone(state, item) {
  return state.agreed[item.n] === true;
}

// Этап готов: картинка согласована (если он за неё отвечает) и все его пункты согласованы.
function stComplete(stages, items, state, approvedUrl, stage) {
  const sc = stScope(stages, stage);
  if (sc.picture && !approvedUrl) return false;
  return sc.items.every(n => { const it = items.find(i => i.n === n); return !it || stItemDone(state, it); });
}

// Текущий этап: первый по порядку незавершённый, который сам ведёт работу (не подчинённый).
function stCurrent(stages, items, state, approvedUrl) {
  return stages.find(s => s.talks !== 'boss' && !stComplete(stages, items, state, approvedUrl, s)) || null;
}

// Обращение по значку («✍️ …») или по имени («Писателю: …»).
function stAddressed(stages, text) {
  const t = String(text || '').trim();
  for (const s of stages) {
    const ic = bareIcon(s.icon);
    if (ic && bareIcon(t).startsWith(ic)) return { stage: s, rest: bareIcon(t).slice(ic.length).replace(/^[\s:,.!—–-]+/, '') };
  }
  const first = (t.match(/^[\p{L}-]+/u) || [''])[0].toLowerCase();
  if (first.length >= 4) {
    // сначала по первому слову имени («Писателю»), потом по любому («Техническому»)
    for (const pass of [0, 1]) {
      for (const s of stages) {
        const words = s.name.toLowerCase().split(/\s+/);
        for (const word of pass === 0 ? words.slice(0, 1) : words.slice(1)) {
          if (word.length < 5) continue;
          const stem = word.slice(0, word.length - 2);
          if (first.startsWith(stem) && first.length <= word.length + 2) {
            // остальные слова имени («Техническому писателю: …») тоже убираем
            let rest = t.slice(first.length).replace(/^[\s:,.!—–-]+/, '');
            for (const w of words.slice(words.indexOf(word) + 1)) {
              const next = (rest.match(/^[\p{L}-]+/u) || [''])[0];
              if (w.length >= 5 && next.toLowerCase().startsWith(w.slice(0, w.length - 2))) rest = rest.slice(next.length).replace(/^[\s:,.!—–-]+/, '');
            }
            return { stage: s, rest };
          }
        }
      }
    }
  }
  return null;
}

// ── Знания этапа из Templates: все колонки со значком этапа ──
// 📍 в заголовке: колонка из блоков «НАЗВАНИЕ: слово, слово» (через пустую строку);
// блок берётся, только если одно из слов встретилось в задании (ловится по началу слова).
// Строка-ссылка — картинка; строка сразу под ссылкой — её роль.
function kbIsService(key) { return !isEmojiStart(key) || key.includes('⚙'); }
function kbLabel(key) { return key.replace(/^[^a-zA-Z]+/, '').replace(/^tmpl_/, ''); }
const URL_LINE = /^https?:\/\/\S+$/;
function toDirectImageUrl(url) {
  const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/) || url.match(/[?&]id=([a-zA-Z0-9_-]+)/);
  return m ? 'https://lh3.googleusercontent.com/d/' + m[1] + '=s2000' : url;
}
function triggered(words, text) {
  const low = String(text || '').toLowerCase();
  const esc = w => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return words.some(w => w && new RegExp('(^|[^\\p{L}\\p{N}])' + esc(w), 'u').test(low));
}
// Текст и картинки одного куска колонки.
function kbSplit(text) {
  const lines = String(text || '').split('\n');
  const keep = [];
  const images = [];
  let last = null;
  for (const line of lines) {
    const t = line.trim();
    if (URL_LINE.test(t)) { last = { url: toDirectImageUrl(t), role: '' }; images.push(last); continue; }
    if (t && last && !last.role) { last.role = t; continue; }
    if (t) last = null;
    keep.push(line);
  }
  return { text: keep.join('\n').trim(), images };
}
function kbForStage(tmpl, icon, taskText, opts) {
  const o = opts || {};
  const ic = bareIcon(icon);
  const parts = [];
  const images = [];
  const notesKey = Object.keys(tmpl || {}).find(k => !kbIsService(k) && bareIcon(k).includes(ic) && k.includes('📝')) || '';
  for (const key of Object.keys(tmpl || {})) {
    if (kbIsService(key)) continue;
    if (!bareIcon(key.match(/^[^a-zA-Z]*/)[0]).includes(ic)) continue;
    const raw = String(tmpl[key] == null ? '' : tmpl[key]);
    if (!raw.trim()) continue;
    let chunks = [raw];
    if (key.includes('📍')) {
      chunks = raw.split(/\n\s*\n/).filter(b => {
        const head = b.trim().split('\n')[0] || '';
        const i = head.indexOf(':');
        const words = i > 0 ? [head.slice(0, i), ...head.slice(i + 1).split(',')].map(w => w.trim().toLowerCase()) : [];
        return words.length && triggered(words, taskText);
      });
    }
    const texts = [];
    for (let c of chunks) {
      // у 📍-блока первая строка — название и слова-триггеры, это механика, не знание
      if (key.includes('📍')) c = c.trim().split('\n').slice(1).join('\n');
      const sp = kbSplit(c);
      if (sp.text) texts.push(sp.text);
      images.push(...sp.images.map(i => ({ ...i, place: key.includes('📍') })));
    }
    if (texts.length) parts.push((o.labels === false ? '' : kbLabel(key) + ':\n') + texts.join('\n\n'));
  }
  return { text: parts.join('\n\n'), images, notesKey, notes: notesKey ? String(tmpl[notesKey] || '') : '' };
}

// ── Пункты: показ и запись в таблицу ──
function itValue(state, n) { const v = state.items[n]; return v && typeof v === 'object' ? v : { text: '', ru: '' }; }
function itShow(state, item) {
  const v = itValue(state, item.n);
  if (!(item.n in state.items)) return '';
  if (!v.text) return '— пусто';
  if (!v.ru) return v.text;
  return v.text.includes('\n') || v.text.length > 200 ? `${v.text}\n\n— Перевод для автора —\n${v.ru}` : `${v.text} (${v.ru})`;
}

// Колонки пункта: «a, b» — одно значение в обе; «a | b» — значение делится по «|»;
// одна колонка у нескольких пунктов — значения склеиваются через пустую строку по порядку.
function itFields(items, state) {
  const acc = {};
  const order = [];
  const put = (col, val) => { if (!(col in acc)) { acc[col] = []; order.push(col); } if (val) acc[col].push(val); };
  for (const it of items) {
    const text = itValue(state, it.n).text || '';
    if (it.cols.includes('|')) {
      const cols = it.cols.split('|').map(c => c.trim()).filter(Boolean);
      const vals = text.split('|').map(v => v.trim());
      cols.forEach((c, i) => put(c, vals[i] || ''));
    } else {
      for (const c of it.cols.split(',').map(c => c.trim()).filter(Boolean)) put(c, text);
    }
  }
  const out = {};
  for (const c of order) out[c] = acc[c].join('\n\n');
  return out;
}

// Стена перед сборщиком: проверяем то, что РЕАЛЬНО лежит в таблице.
// Обязательны колонки пунктов, которые нельзя оставить пустыми.
function validateRow(row, items, opts) {
  const o = opts || {};
  const problems = [];
  const val = k => String(row[k] == null ? '' : row[k]).trim();
  for (const it of items) {
    if (it.canEmpty) continue;
    for (const c of it.cols.split(/[|,]/).map(c => c.trim()).filter(Boolean)) {
      if (!val(c) && !problems.includes(`${c} пустая`)) problems.push(`${c} пустая (пункт ${it.n}. ${it.name})`);
    }
  }
  if (!val('ai_ApprovedImageUrl')) problems.push('ai_ApprovedImageUrl пустая (нет согласованной картинки)');
  // Метка [Timecodes] — место, куда сборщик вставит тайм-коды (механика 04_Video).
  if (val('ai_TimecodeNames') && val('ai_Description') && !/\[?Timecodes\]?/i.test(val('ai_Description'))) {
    problems.push('в ai_Description нет метки [Timecodes]');
  }
  if (o.needApproved && val('sys_Status') !== 'Утверждено') problems.push(`статус «${val('sys_Status') || 'пусто'}», а не «Утверждено»`);
  if (o.needTracks && !val('sys_AudioZipUrl')) problems.push('sys_AudioZipUrl пустая (нет ссылки на треки)');
  return problems;
}

// Референсы художнику: картинки из колонок 🎨 — до 16 (в правке 15).
// Картинки 📍-мест (названных в задании) остаются, общие сокращаются с конца.
function artRefs(kbImages, placeImages) {
  const fit = max => {
    const room = Math.max(1, max - placeImages.length);
    return [...kbImages.slice(0, room), ...placeImages].slice(0, max);
  };
  const roles = (list, shift) => {
    const parts = list.map((r, i) => (r.role ? `Image ${i + 1 + shift} — ${r.role}.` : '')).filter(Boolean);
    return parts.length ? 'Reference images: ' + parts.join(' ') + '\n\n' : '';
  };
  const draw = fit(16);
  const edit = fit(15);
  return { drawRefUrls: draw.map(r => r.url), drawRoles: roles(draw, 0), editRefUrls: edit.map(r => r.url), editRoles: roles(edit, 1) };
}
// Применяем предложения этапа к пунктам — только в пределах его пунктов (scope).
// Изменённый пункт снова ждёт согласования. Возвращает номера изменённых пунктов.
function itApply(state, items, scope, args, autoAgree) {
  const changed = [];
  const inScope = n => scope.includes(n) && items.some(i => i.n === n);
  for (const p of (Array.isArray(args.items) ? args.items : [])) {
    const n = parseInt(p && p.n, 10);
    if (!inScope(n)) continue;
    let text = String(p.text == null ? '' : p.text).trim();
    if (text === '-') text = '';
    const ru = String(p.ru == null ? '' : p.ru).trim();
    const old = state.items[n];
    if (!old || old.text !== text || (ru && old.ru !== ru)) {
      if (!old || old.text !== text) { state.agreed[n] = false; changed.push(n); }
      state.items[n] = { text, ru: ru || (old && old.text === text ? old.ru || '' : '') };
    }
    if (autoAgree) state.agreed[n] = true;
  }
  for (const raw of (args.reopen || [])) {
    const n = parseInt(raw, 10);
    if (inScope(n) && state.agreed[n]) { state.agreed[n] = false; if (!changed.includes(n)) changed.push(n); }
  }
  for (const raw of (args.agreed || [])) {
    const n = parseInt(raw, 10);
    if (!inScope(n)) continue;
    const it = items.find(i => i.n === n);
    if (!(n in state.items) && it.canEmpty) state.items[n] = { text: '', ru: '' };
    if (n in state.items) state.agreed[n] = true;
  }
  return changed;
}

// Задание художнику: знания колонок его значка (без подписей) + слова задания.
// Новая картинка — правила и описание мест + сцена; правка — только слова правки.
function artBuild(ctx, stage, task, edit, variantNumber) {
  const row = ctx.row || {};
  const tmpl = ctx.tmpl || {};
  let variants = [];
  try { variants = JSON.parse(row.ai_ImageVariants || '[]'); } catch (e) { variants = []; }
  if (!Array.isArray(variants)) variants = [];
  const last = variants.length ? variants[variants.length - 1] : null;
  const kb = kbForStage(tmpl, stage.icon, task, { labels: false });
  const refs = artRefs(kb.images.filter(i => !i.place), kb.images.filter(i => i.place));
  const r = {
    action: edit ? 'revise_point' : 'ready_to_draw',
    messageToUser: '',
    dallePrompt: '', revisionInstruction: '', revisionIsNewVariant: true,
    revisionTargetImageUrl: String(row.ai_ImageUrl || ''), revisionTargetVariantNumber: last ? last.n : 1,
    imageModel: stage.model || String(findByLabel(tmpl, 'tmpl_ImageModel') || '').trim() || 'gpt-image-2',
    ...refs,
  };
  if (edit) {
    const target = variantNumber ? variants.find(v => Number(v.n) === Number(variantNumber)) : last;
    if (target && target.url) { r.revisionTargetImageUrl = target.url; r.revisionTargetVariantNumber = target.n; }
    else { r.action = 'chat'; r.messageToUser = variantNumber ? `Не нашла вариант ${variantNumber}. Есть: ${variants.map(v => v.n).join(', ') || 'пока ни одного'}.` : 'Править пока нечего — сначала нужна картинка.'; }
    r.revisionInstruction = task;
  } else {
    r.dallePrompt = [kb.text, task].filter(Boolean).join('\n\n');
  }
  if (r.action !== 'chat' && !String(task || '').trim()) { r.action = 'chat'; r.messageToUser = 'Напишите задание словами.'; }
  return r;
}
// ── конец общего куска ─────────────────────────────────────────────────────

// Одно сообщение с единственной финальной кнопкой — после всех кусков сводки.
const s = $('Сводка').first().json;
return [{ json: { chatId: s.chatId, text: s.buttonText, callbackData: s.callbackData } }];

// Референсы художнику — список уже собран и уложен в 16 картинок в «Итог хода».
const j = $('Итог хода').first().json;
const urls = (j.drawRefUrls || []).filter(Boolean).slice(0, 16);
return urls.map((url, i) => ({ json: { ...j, refUrl: url, refIndex: i } }));

const binary = {};
