return [{ json: { chatId: ctx.chatId, text, hasTracks: chk.hasTracks, callbackData: `build|${ctx.projectId}`, buttonText: `👇 Собрать видео с этими треками?\n\nID: ${ctx.projectId}` } }];

const ctx = $('Контекст проекта').first().json;
